    adcs_quat_t q_n;
    adcs_mat3_t c_bi;
    adcs_mat3_t c_bi_t;
    adcs_mat3_t tmp;
    double norm;
    size_t i, j;

    if ((q_bi == NULL) || (covariance_i == NULL) || (covariance_b == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!isfinite(q_bi->w)) || (!isfinite(q_bi->x)) || (!isfinite(q_bi->y)) || (!isfinite(q_bi->z))) {
        return ADCS_E_RANGE;
    }
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (!isfinite(covariance_i->m[i][j])) {
                return ADCS_E_RANGE;
            }
        }
    }

    norm = sqrt(q_bi->w * q_bi->w + q_bi->x * q_bi->x + q_bi->y * q_bi->y + q_bi->z * q_bi->z);
    if ((!isfinite(norm)) || (norm <= 1.0e-12)) {
        return ADCS_E_DEGENERATE;
    }

    q_n.w = q_bi->w / norm;
    q_n.x = q_bi->x / norm;
    q_n.y = q_bi->y / norm;
    q_n.z = q_bi->z / norm;

    c_bi = adcs_quat_to_dcm_bi(&q_n);
    tmp = adcs_mat3_mul(&c_bi, covariance_i);
    c_bi_t = adcs_mat3_transpose(&c_bi);
    *covariance_b = adcs_mat3_mul(&tmp, &c_bi_t);

    return ADCS_OK;
}

